  "图像描述": "一张细节丰富、写实主义风格的棚拍肖像，主角是一位惊艳的年轻女性，留着黑色长波浪发，皮肤白皙，带有天然雀斑，双眼呈现迷人的蓝绿色。她坐在地板上，背靠纯黑背景，姿态极具戏剧感，双膝抬起，双腿分开，一只手穿过头发。她穿着一件修身的白色短连衣裙，带有交叉挂脖领口，脚蹬亮面的白色高跟鞋。她的表情自信而略显脆弱，直视镜头。",
  "构图": "低角度中景全身棚拍，专注于她的姿势、身材和面部表情。戏剧性的高对比度影棚照明，在皮肤、头发和亮面鞋子上产生柔和的高光，营造出性感而优雅的氛围。",
  "细节": {
    "女性": "20多岁的美丽女性，身材苗条健美，长波浪黑发，富有表现力的眼睛，带有亮面唇彩的自然妆容。",
    "服装": "修身白色连衣裙，交叉挂脖领口，亮面白色高跟鞋。",
    "环境": "极简主义黑色影棚背景。",
    "道具": "无额外道具。"
  },
  "修改": {
    "添加": "在她白色连衣裙的可见边缘或下摆处，添加一个小巧而优雅的刺绣标识，内容为精美的草体字‘Keor’。将其逼真地放置在下摆、领口边缘或侧缝处，使用细腻的白色或金属丝线，自然地融入其中，展现出高端定制的微妙细节。"
  },
  "风格": "写实主义、高分辨率魅力写真人像摄影，戏剧性影棚照明，对被摄主体锐利聚焦，真实的皮肤纹理、发量、白色连衣裙的面料垂感以及高跟鞋的亮面反射，自信且诱惑的情绪。",
  "技术": {
    "分辨率": "8K",
    "纵横比": "纵向",
    "质量": "极具细节的波浪发丝、带有天然雀斑的皮肤纹理、真实的白色面料褶皱和光泽、亮面白色高跟鞋，以及微妙的‘Keor’刺绣标识。"
  },
  "完整提示词": "绝美黑发女性的写实主义棚拍肖像，身穿修身短款白色挂脖连衣裙，坐在地板上，双膝抬起，手抚头发，戏剧性黑色背景，自信的眼神，在白色连衣裙的边缘下摆添加微妙的‘Keor’刺绣 --ar 2:3 --v 6 --q 2 --stylize 250"
}

